source_context:
 5:     - nfs-common
 6: 
 7: - name: Create nfs_export directory
 8:   file: path={{ nfs_export_galaxy_dir }} state=directory mode=0755 recurse=yes
 9: 
10: - name: bind mount persitent directories in nfs_export/galaxy directory
11:   mount: opts=bind fstype=none state=mounted name={{ item.dest }} src={{ item.src }}
12:   with_items:
13:     - { src: "/home/galaxy", dest: "{{ nfs_export_galaxy_dir }}" }
14:     - { src: "{{ galaxy_persistent_directory }}/home/galaxy/tool_dependencies", dest: "{{ nfs_export_galaxy_dir }}/tool_dependencies" }
15:     - { src: "{{ galaxy_persistent_directory }}/home/galaxy/shed_tools", dest: "{{ nfs_export_galaxy_dir }}/shed_tools" }
16:     - { src: "{{ galaxy_persistent_directory }}{{ galaxy_server_dir }}/tool-data", dest: "{{ nfs_export_galaxy_dir }}/galaxy/tool-data" }
17:     - { src: "{{ galaxy_persistent_directory }}{{ galaxy_server_dir }}/config", dest: "{{ nfs_export_galaxy_dir }}/galaxy/config" }
18:     - { src: "{{ galaxy_persistent_directory }}{{ galaxy_server_dir }}/database", dest: "{{ nfs_export_galaxy_dir }}/galaxy/database" }
19: 
20: - name: export galaxy data for nfs sharing with slurm slave nodes
21:   template: src=exports dest=/etc/exports
22: #  notify:
23: #    - restart nfs-kernel-server
24: 
25: - name: restart nfs-kernel-server
26:   service: name=nfs-kernel-server state=restarted

 81:     - assert: { that: "vault_write is not changed" }
 82:     - assert: { that: "'did not match the current version' in vault_write.msg" }
 83:     - assert: { that: "vault_write.rc == 1" }
 84: 
 85: 
 86:     - name: no cas kv2 write fail
 87:       hashivault_write:
 88:         mount_point: kv2
 89:         secret: casy
 90:         version: 2
 91:         data:
 92:             value: firstvalue
 93:       failed_when: False
 94:       register: vault_write
 95:     - assert: { that: "vault_write is not changed" }
 96:     - assert: { that: "'check-and-set parameter required' in vault_write.msg" }
 97:     - assert: { that: "vault_write.rc == 1" }
 98: 
 99:     - name: Disable kv2 secret store
100:       hashivault_secret_engine:
101:         name: "kv2"
102:         state: absent
103:       register: 'vault_secret_disable'
104:     - assert: { that: "vault_secret_disable is changed" }
105:     - assert: { that: "vault_secret_disable.rc == 0" }

