17: - name: EDPM Hugepages configuration
18:   vars:
19:     _converted_hugepages: {}
20:     _nonconfig_hugepages: {}
21:     _hugepages_modification: false
22:   when: edpm_kernel_hugepages | default({}) | length > 0
23:   block:
24:     - name: Rewrite edpm_kernel_hugepages to use integers as keys
25:       ansible.builtin.set_fact:
26:         _edpm_kernel_hugepages: "{{ _edpm_kernel_hugepages | default({}) | combine({hp.key | int: hp.value}) }}"
27:       loop: "{{ edpm_kernel_hugepages | dict2items }}"
28:       loop_control:
29:         loop_var: hp
30: 
31:     - name: Parsing running hugepage configuration from /proc/cmdline
32:       when: >
33:         "default_hugepagesz" in cmdline
34:       ansible.builtin.import_tasks: hugepages_parsing.yaml
35:       vars:
36:         cmdline_text: "{{ cmdline }}"
37: 
38:     - name: Validating hugepage config from /proc/cmdline against EDPM parameter
39:       ansible.builtin.import_tasks: hugepages_validations.yaml
40: 
41:     - name: Rewrite kernel args
42:       when: _hugepages_modification
43:       block:
44:         - name: Warn about possible modifications
45:           ansible.builtin.debug:
46:             msg: |
47:               EDPM hugepage modification differs from how the host is actually having.
48:               Current default pagesize: {{ _configured_default_size | default("None configured") }}
49:               EDPM default pagesize: {{ _edpm_default_hugepages }}
50:               Desired default pagesize: {{ _desired_default_hugepages }}
51: 
52:               From EDPM Hugepages configuration:
53:               {% for pagesize, config in _edpm_kernel_hugepages.items() %}
54:               - {{ pagesize }}
55:                 expected: {{ config.count }} pages
56:                 default: {{ config.default | default(false) }}
57:                 current: {{ _converted_hugepages.get(pagesize | int, 0) }}
58:               {% endfor %}
59:               {% if _nonconfig_hugepages | length %}
60:               There's also some hugepages on the host that are not part of the EDPM configuration
61:               {% for pagesize, config in _nonconfig_hugepages.items() %}
62:               - {{ pagesize }}: {{ config }} pages
63:               {% endfor %}
64:               {% endif %}
65: 
66:         - name: Remove hugepage settings from kernelargs
67:           ansible.builtin.set_fact:
68:             _kernel_args: >-
69:               {{ edpm_kernel_args | regex_replace('[\s]*(default_)*hugepages[z]*=[\S]+[\s]*', ' ') }}
70:               default_hugepagesz={{ _desired_default_hugepages }}
71:               {% for hp, values in _edpm_kernel_hugepages.items() -%}
72:               hugepagesz={{ hp }} hugepages={{ values.count }}
73:               {% endfor -%}
74:               {% if not edpm_kernel_hugepages_remove | bool -%}
75:               {% for hp, values in _nonconfig_hugepages.items() -%}
76:               hugepagesz={{ hp }} hugepages={{ values }}
77:               {% endfor -%}
78:               {% endif -%}
79: 
80:         - name: Cleaning up whitespaces
81:           ansible.builtin.set_fact:
82:             edpm_kernel_args: >-
83:               {{ _kernel_args |
84:                 regex_replace('[\s]+default_hugepagesz=', ' default_hugepagesz=') |
85:                 regex_replace('[\s]+', ' ') |
86:                 regex_replace('[\s]+$', '')
87:               }}

